rline span{display:inline-block;width:17px;height:1px;background:#ccd99c;vertical-align:middle;margin-right:6px}.intro-copy h1{font:600 clamp(42px,5vw,64px)/.99 var(--display);letter-spacing:1.1px;margin:28px 0 14px}.intro-copy h1 em,.death-panel h2 em{font-style:normal;color:#c4d18e}.intro-copy p{font-size:12px;line-height:1.8;color:#b9c0ad;max-width:260px}.intro-stats{display:flex;align-items:center;gap:13px;margin-top:48px}.intro-stats div strong{display:block;font:500 20px var(--display);color:#e5e8d4}.intro-stats div span{display:block;color:#a8b094;font-size:7px;letter-spacing:1.1px;margin-top:2px;white-space:nowrap}.intro-stats i{height:25px;width:1px;background:#e6e9d129}.lineage-select{padding:35px 36px 27px 30px;position:relative}.select-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.select-heading h2{font:500 25px var(--display);letter-spacing:.4px;margin:4px 0 0}.step-count{font:500 12px var(--display);color:#dfe3ce;letter-spacing:1px}.step-count i{font-style:normal;color:#737b69}.class-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.class-card{position:relative;display:flex;flex-direction:column;text-align:left;min-height:149px;padding:12px 13px 11px;background:rgba(224,231,207,.035);border:1px solid rgba(220,230,201,.12);transition:.2s}.class-card:hover{background:#d5dfad0c;border-color:#d6e2a853}.class-card.selected{background:rgba(181,200,125,.09);border-color:#c3d28a}.class-glyph{position:absolute;right:12px;top:9px;color:#bdca8d;font-size:21px}.class-name{font:500 18px var(--display);letter-spacing:1.3px}.class-creature{color:#bec6a9;font-size:9px;margin-top:0}.class-trait{font-size:7px;letter-spacing:1.2px;color:#c5d295;margin-top:10px}.class-desc{font-size:9px;line-height:1.45;color:#aab29e;margin-top:4px;max-width:200px}.class-stat{position:absolute;bottom:0;left:0;right:0;height:2px;background:#dce1cb16}.class-stat i{display:block;height:100%;background:#afc27c}.selection-footer{display:flex;alig