  if(player.hunger<=0||player.thirst<=0)player.hp=Math.max(0,player.hp-(player.hunger<=0?4:2.5)*dt);
  player.attackCooldown=Math.max(0,player.attackCooldown-dt);player.invuln=Math.max(0,player.invuln-dt);attackFX=Math.max(0,attackFX-dt);
  for(const a of animals){if(!a.alive)continue;a.think-=dt;const d=Math.hypot(player.x-a.x,player.y-a.y);if(a.kind==='pred'&&d<245){a.alert=Math.max(a.alert,2);a.angle=Math.atan2(player.y-a.y,player.x-a.x);a.x+=Math.cos(a.angle)*(a.speed+20)*dt;a.y+=Math.sin(a.angle)*(a.speed+20)*dt;if(d<29&&player.invuln<=0){player.hp=Math.max(0,player.hp-(10*(1-(player.armor||0))));player.invuln=.8;notify(`${a.name} attacks! Keep moving.`)}}else if(a.alert>0){a.alert-=dt;if(a.kind==='herb'&&d<180){a.angle=Math.atan2(a.y-player.y,a.x-player.x);a.x+=Math.cos(a.angle)*a.speed*2*dt;a.y+=Math.sin(a.angle)*a.speed*2*dt}}else if(a.think<=0){a.think=rand(1.8,4.7);a.angle=rand(0,6.28)}else{a.x+=Math.cos(a.angle)*a.speed*.32*dt;a.y+=Math.sin(a.angle)*a.speed*.32*dt}
